double totalEnergy = 0.0;
for (size_t i = 0; i < velocities.size(); i++) {
    double vx = velocities[i].x;
    double vy = velocities[i].y;
    double vz = velocities[i].z;
    double speedSquared = vx * vx + vy * vy + vz * vz;
    totalEnergy += 0.5 * masses[i] * speedSquared;
}
return totalEnergy;

